    for m in cit.finditer(line):
        name,fp,num=m.group(1),m.group(2),int(m.group(3))
        # file: explicit else last file mention before
        if fp: f=short(fp)
        else:
            prev=[x for x in fileref.finditer(line[:m.start()])]
            f=short(prev[-1].group(1)) if prev else None
            cands=nsfile(name)
            if cands and len(cands)==1 and (f is None or not name.split('.')[0] in ('Lib','Corpus','Refinement','RefinementArena','Arena','Machine') or True):
                if cands and f not in cands and len(cands)==1 and name.count('.')>=1 and name.split('.')[0] in ('Lib','Corpus','Refinement','RefinementArena','Arena','Machine'): f=cands[0]
        last=name.split('.')[-1]
