            txt=files[f][num-1]
            ok=re.search(r'\b(theorem|def|structure|inductive|abbrev|lemma|instance|class)\s+(\S+\.)?'+re.escape(last)+r'\b',txt) is not None or re.search(r'^\s*\|\s*'+re.escape(last)+r'\b',txt) is not None
        if not ok:
            # find actual
            found=[]
            for k,L in files.items():
